import { user } from "@app/model";
import { ButtonConfirm, useProxyWatch, useTranslation } from "@fanfanlo";
import { autoWebViewJs } from '@droid/android';
import { Button, Box } from "@mui/material";


export function LogoutButton(){
    const { t } = useTranslation('homepage/components/logout/content');
    const onSignoutClick = () => {
        user.signout();
        // 通知安卓端退出
        const script = `com.fanfanlo.droid.auth.FirebaseAuthManager.logout()`;
        autoWebViewJs.callScript(script);
    }   
    return(
        
                    <Box>
                        <Box>
                            <span>
                                {user.userName}
                            </span>
                        </Box>
                        <Box>
                        <span>
                            <ButtonConfirm title={t('LogoutButton.confirmTitle')} content={t('LogoutButton.confirmContent')} onConfirm={onSignoutClick}><Button>{t('LogoutButton.signOut')}</Button></ButtonConfirm>
                        </span>
                        </Box>
                    </Box>
    )
}

export function LogoutButtonBox(){
    const [userToken] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token);
    console.log('LogoutButtonBox userToken=', userToken);
    console.log('LogoutButtonBox userToken=', user);
    if(!userToken){
        return <></>;
    }   
    return(
        <Box><LogoutButton /></Box>
    )   
}